import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"19、【臨】 兌下坤上","description":"子夏易傳 - 19、【臨】 兌下坤上","frontmatter":{"title":"19、【臨】 兌下坤上","description":"子夏易傳 - 19、【臨】 兌下坤上"},"headers":[],"relativePath":"classics/zixia/021.md","filePath":"classics/zixia/021.md"}'),i={name:"classics/zixia/021.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_19、【臨】-兌下坤上" tabindex="-1">19、【臨】 兌下坤上 <a class="header-anchor" href="#_19、【臨】-兌下坤上" aria-label="Permalink to “19、【臨】 兌下坤上”">​</a></h1><p>卦辭：臨，元亨利貞。至於八月，有兇。</p><p>彖曰：臨剛浸而長，說而順，剛中而應，大亨。以正天之道也。至於八月，有兇。消不乆也。</p><p>子夏：隂陽迭盛，天道成焉。陽長而萬物生，君子之道行，小人望之而服也。剛長正以應，說而順之，大亨，以正也。夫物有長也，必有代也。陽雖維隂，至於隂盛則不復維矣。君子當其時，內惕而不自得焉。觀時之消息也。臨代坤之二也。極六位而隂及代之矣。數之變也。兇其乆乎。月隂之物來，代陽也，故八月兇。</p><p>象曰：澤上有地，臨。君子以敎思無窮，容保民無疆。</p><p>子夏：澤上有地，地取潤於澤。剛臨於柔，小人取，則於君子思其敎，周而無已也。則能保民安眾而應其無疆也。</p><p>初九，鹹臨貞吉。</p><p>象曰：鹹臨貞吉，志行正也。</p><p>子夏：四為我應，能感柔也。則制之自我矣。豈肆其志哉。感其從正者也。故得吉矣。</p><p>九二，鹹臨吉無不利。</p><p>象曰：鹹臨吉無不利，未順命也。</p><p>子夏：剛浸而長，履位得中，有其德而能感。五以從已也。則五順於二，二未盡順於五也。尊而順，剛德日崇，故無不利也。</p><p>六三，甘臨，無利攸。既憂之，無咎。</p><p>象曰：甘臨，位不當也。</p><p>子夏：既憂之，咎不長也。隂以居上，柔接以臨之，甘辭以說之，失其正也。下有其人，而悟其非道，而能憂之，則咎不長也。</p><p>六四，至臨無咎。</p><p>象曰：至臨無咎，位當也。</p><p>子夏：應於初，則剛之。敎而守當其位，盡柔之道，臨之至也。無憂邪之，咎矣。</p><p>六五，知臨大君之宜，吉。</p><p>象曰：大君之宜，行中之謂也。</p><p>子夏：二以剛長，五能感而從焉，知之以能，授之以政，可謂智矣。大君之宜，能臨天下者，如此矣。行能得其中也。</p><p>上六，敦臨，吉，無咎。</p><p>象曰：敦臨之吉，志在內也。</p><p>子夏：四五皆應於陽，上為至順，亦歸而從之，逺而志於陽，厚於君子之道，順時知機，吉。又何咎哉。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
